fun greet(name: String?): String {
    val n = name ?: "anonymous"
    return "hi, $n"
}

fun firstOrDefault(xs: List<Int>): Int {
    return xs.firstOrNull() ?: 0
}

fun dump(m: Map<String, Int>) {
    for ((k, v) in m) {
        println("$k: $v")
    }
}

fun indexed(xs: List<String>): List<String> {
    val out = mutableListOf<String>()
    for ((i, v) in xs.withIndex()) {
        out.add("$i: $v")
    }
    return out
}

class Counter {
    companion object {
        var count: Int = 0
        fun inc() { count += 1 }
    }
}

class User(val name: String) {
    companion object {
        fun anonymous() = User("anonymous")
    }
}

fun greet(name: String, age: Int): String {
    return "hi, $name, you are ${age + 1} next year"
}

fun coords(x: Double, y: Double): String {
    return "(${x.toInt()}, ${y.toInt()})"
}

sealed class Shape {
    data class Circle(val r: Double) : Shape()
    data class Square(val side: Double) : Shape()
}

fun area(s: Shape): Double = when (s) {
    is Shape.Circle -> 3.14159 * s.r * s.r
    is Shape.Square -> s.side * s.side
}

fun describe(n: Int): String = when {
    n < 0 -> "negative"
    n == 0 -> "zero"
    n < 10 -> "small"
    else -> "big"
}

fun label(x: Any): String = when (x) {
    is String -> "string"
    is Int -> "int"
    else -> "unknown"
}

suspend fun fetchUser(id: Int): String {
    delay(100)
    return "user_$id"
}

suspend fun fetchAll(ids: List<Int>): List<String> = coroutineScope {
    ids.map { async { fetchUser(it) } }.map { it.await() }
}

fun squared(xs: List<Int>): List<Int> {
    return xs.map { it * it }
}

fun positives(xs: List<Int>): List<Int> {
    return xs.filter { it > 0 }
}

fun process(x: Int?): Int {
    return x?.let { it * 2 } ?: 0
}

fun makeList(): List<Int> {
    return listOf(1, 2, 3, 4, 5)
}

fun makeMap(): Map<String, Int> {
    return mapOf("a" to 1, "b" to 2)
}

fun length(s: String?): Int {
    return s?.length ?: 0
}

fun upper(s: String?): String? {
    return s?.uppercase()
}

enum class Direction {
    NORTH, SOUTH, EAST, WEST
}

interface Speakable {
    fun speak(): String
}
class Dog(val name: String) : Speakable {
    override fun speak(): String = "$name barks"
}

fun safeDivide(a: Int, b: Int): Int? {
    return try {
        a / b
    } catch (e: ArithmeticException) {
        null
    }
}

fun <T, R> List<T>.mapIndexedTo(f: (Int, T) -> R): List<R> {
    val out = mutableListOf<R>()
    for ((i, v) in this.withIndex()) {
        out.add(f(i, v))
    }
    return out
}

fun <T> repeat(n: Int, f: () -> T): List<T> {
    val out = mutableListOf<T>()
    for (i in 0 until n) {
        out.add(f())
    }
    return out
}

fun sum1toN(n: Int): Int {
    var total = 0
    for (i in 1..n) {
        total += i
    }
    return total
}

fun countdown(n: Int): Int {
    var i = n
    var steps = 0
    while (i > 0) {
        i--
        steps++
    }
    return steps
}

class Animal(val name: String) {
    fun speak(): String = "$name makes a sound"
}

fun counter(start: Int): Flow<Int> = flow {
    var n = start
    while (n < start + 5) {
        emit(n)
        n += 1
    }
}

object Singleton {
    var count: Int = 0
    fun inc() {
        count++
    }
}

class Temp(var celsius: Double) {
    val fahrenheit: Double
        get() = celsius * 9 / 5 + 32
}

fun renamed(u: User, newName: String): User {
    return u.copy(name = newName)
}

fun normalize(s: String): String {
    return s.trim().lowercase()
}

fun sortedUnique(xs: List<Int>): List<Int> {
    return xs.distinct().sorted()
}

fun product(xs: List<Int>): Int {
    return xs.fold(1) { acc, x -> acc * x }
}

fun vowelsCount(s: String): Int {
    return s.lowercase().count { it in "aeiou" }
}
